1	export type Item = {
2	  type: string;
3	  cursed?: boolean;
4	  enchantment?: number;
5	};
6	
7	export type Customer = {
8	  yearsWithMHPCO: number;
9	};
10	
11	export type Damage = {
12	  itemType: string;
13	  amount: number;
14	};
15	
16	export type Incident = {
17	  cause: string;
18	  damages: Damage[];
19	};
20	
21	/**
22	 * One type covers both ops, so items/policy/incident are all optional. A
23	 * discriminated union on `op` would express this better, but the spec's
24	 * scenarios are plain object literals whose `op` widens to `string` and so
25	 * would no longer typecheck against literal `"quote"` / `"claim"` variants.
26	 * Revisit if a scenario parser ever narrows `op` on the way in.
27	 */
28	export type Step = {
29	  op: string;
30	  items?: Item[];
31	  policy?: number;
32	  incident?: Incident;
33	};
34	
35	export type Scenario = {
36	  customer: Customer;
37	  steps: Step[];
38	};
39	
40	export type QuoteResult = { premium: number };
41	export type ClaimResult = { payout: number; remainingCap: number };
42	
43	export type ScenarioResult = {
44	  results: (QuoteResult | ClaimResult)[];
45	};
46	
47	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
48	  sword: 100,
49	  amulet: 60,
50	  staff: 80,
51	  potion: 40,
52	  rune: 25,
53	  moonstone: 25,
54	};
55	/**
56	 * Deliberately NOT derived from the base premiums, though every entry today
57	 * happens to be 10x its counterpart. The MHPCO publishes two independent
58	 * price lists ("Sword: 1000 G insurance value, 100 G base premium"), and the
59	 * rules already pull them apart: the 3-alike building block cuts the base
60	 * premium to 60 G while the insurance value stays 250 G per component. Making
61	 * one a function of the other would encode a coincidence as a rule.
62	 *
63	 * A test now guards this — "caps a policy covering a sword and 3 runes at
64	 * 3500 G". Deriving these values from the base premiums, or routing both
65	 * through a shared summing helper, makes the block rule reach the insurance
66	 * sum and yields a cap of 2120 instead of 3500.
67	 */
68	const INSURANCE_VALUE_BY_ITEM_TYPE: Record<string, number> = {
69	  sword: 1000,
70	  amulet: 600,
71	  staff: 800,
72	  potion: 400,
73	  rune: 250,
74	  moonstone: 250,
75	};
76	const DEDUCTIBLE = 100;
77	const CAP_MULTIPLE = 2;
78	const HIGH_ENCHANTMENT_PAYOUT_THRESHOLD = 8;
79	const HIGH_ENCHANTMENT_PAYOUT_PERCENT = 50;
80	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
81	const CURSE_SURCHARGE_PERCENT = 50;
82	const HIGH_ENCHANTMENT_THRESHOLD = 5;
83	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
84	const LOYALTY_THRESHOLD_YEARS = 2;
85	const LOYALTY_DISCOUNT_PERCENT = 20;
86	const FOLLOWUP_DISCOUNT_PERCENT = 15;
87	const PROCESSING_FEE = 5;
88	
89	const percentOf = (amount: number, percent: number): number =>
90	  (amount * percent) / 100;
91	
92	/**
93	 * The MHPCO insures only what is on its price list. Looking a type up through
94	 * here rather than indexing a table directly means an unknown type cannot slip
95	 * through as `undefined` and surface later as a NaN premium.
96	 */
97	const priceOf = (
98	  priceList: Record<string, number>,
99	  itemType: string,
100	): number => {
101	  const price = priceList[itemType];
102	  if (price === undefined) {
103	    throw new Error(`unknown item type: ${itemType}`);
104	  }
105	  return price;
106	};
107	
108	/**
109	 * Premiums round UP — the MHPCO's favour on money coming IN. Payouts will need
110	 * the opposite direction, so this deliberately names the premium case only
111	 * rather than a general "in the MHPCO's favour" rounding.
112	 */
113	const roundPremiumUp = (premium: number): number => Math.ceil(premium);
114	
115	const BLOCK_SIZE = 3;
116	const BLOCK_BASE_PREMIUM = 60;
117	
118	/** Counts of items of the same type — "alike" in the MHPCO's terms. */
119	const countAlikeItems = (items: Item[]): Map<string, number> =>
120	  items.reduce(
121	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
122	    new Map<string, number>(),
123	  );
124	
125	const formsBuildingBlock = (count: number): boolean => count === BLOCK_SIZE;
126	
127	const basePremiumForAlikeItems = (type: string, count: number): number =>
128	  formsBuildingBlock(count)
129	    ? BLOCK_BASE_PREMIUM
130	    : count * priceOf(BASE_PREMIUM_BY_ITEM_TYPE, type);
131	
132	const policyBasePremium = (items: Item[]): number =>
133	  [...countAlikeItems(items)].reduce(
134	    (total, [type, count]) => total + basePremiumForAlikeItems(type, count),
135	    0,
136	  );
137	
138	const itemBasePremium = (item: Item): number =>
139	  priceOf(BASE_PREMIUM_BY_ITEM_TYPE, item.type);
140	
141	/**
142	 * An absent `enchantment` reads as 0 — a plain rune is not enchanted at all.
143	 * The threshold is a parameter because the MHPCO sets two different bars: 5
144	 * for the premium surcharge, 8 for the payout clause.
145	 */
146	const enchantmentAtLeast = (item: Item, threshold: number): boolean =>
147	  (item.enchantment ?? 0) >= threshold;
148	
149	const isHighlyEnchanted = (item: Item): boolean =>
150	  enchantmentAtLeast(item, HIGH_ENCHANTMENT_THRESHOLD);
151	
152	/** Item-specific surcharges stack additively. */
153	const itemSurchargePercent = (item: Item): number =>
154	  (item.cursed ? CURSE_SURCHARGE_PERCENT : 0) +
155	  (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE_PERCENT : 0);
156	
157	/**
158	 * Item-specific modifiers are percentages of the AFFECTED ITEM's own base
159	 * premium — unlike policy-wide modifiers, which apply to the policy base.
160	 */
161	const totalItemSurcharges = (items: Item[]): number =>
162	  items.reduce(
163	    (total, item) =>
164	      total + percentOf(itemBasePremium(item), itemSurchargePercent(item)),
165	    0,
166	  );
167	
168	const isLongStanding = (customer: Customer): boolean =>
169	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
170	
171	/**
172	 * The net of all policy-wide percentages. Policy-wide modifiers are
173	 * percentages of the POLICY base premium — unlike item-specific modifiers,
174	 * which apply to the affected item's own base. The net is negative when the
175	 * discounts outweigh the surcharges: a long-standing customer nets -10 %.
176	 */
177	const netPolicyAdjustmentPercent = (
178	  customer: Customer,
179	  precedingSteps: number,
180	): number =>
181	  FIRST_INSURANCE_SURCHARGE_PERCENT -
182	  (isLongStanding(customer) ? LOYALTY_DISCOUNT_PERCENT : 0) -
183	  // The follow-up discount is owed on every quote after the customer's FIRST
184	  // QUOTE, but what we have here is a count of preceding STEPS. The two
185	  // coincide only because every step exercised so far is a quote; once claim
186	  // steps arrive, [quote, claim, quote] will wrongly discount the third step
187	  // as a second follow-up. No test forces the distinction yet.
188	  (precedingSteps > 0 ? FOLLOWUP_DISCOUNT_PERCENT : 0);
189	
190	const policyAdjustment = (
191	  policyBase: number,
192	  customer: Customer,
193	  precedingSteps: number,
194	): number =>
195	  percentOf(policyBase, netPolicyAdjustmentPercent(customer, precedingSteps));
196	
197	const quotePremium = (
198	  items: Item[],
199	  customer: Customer,
200	  precedingSteps: number,
201	): number => {
202	  const basePremium = policyBasePremium(items);
203	  return roundPremiumUp(
204	    basePremium +
205	      totalItemSurcharges(items) +
206	      policyAdjustment(basePremium, customer, precedingSteps) +
207	      PROCESSING_FEE,
208	  );
209	};
210	
211	const roundPayoutDown = (payout: number): number => Math.floor(payout);
212	
213	/**
214	 * Goes through `priceOf` for the same reason the premium side does: an unknown
215	 * type would otherwise index to `undefined` and sum to a NaN cap, which
216	 * `Math.min` would carry into a NaN payout instead of an error. This is a
217	 * guarded lookup, not a derivation — the two price lists stay independent.
218	 */
219	const insuranceSum = (items: Item[]): number =>
220	  items.reduce(
221	    (sum, item) => sum + priceOf(INSURANCE_VALUE_BY_ITEM_TYPE, item.type),
222	    0,
223	  );
224	
225	/**
226	 * The MHPCO settles damage only to what it insures. Throwing here rather than
227	 * returning undefined means an uninsured item — including one of an unknown
228	 * type, which is likewise not in the policy — cannot be quietly paid out.
229	 */
230	const damagedItem = (damage: Damage, policyItems: Item[]): Item => {
231	  const item = policyItems.find((it) => it.type === damage.itemType);
232	  if (item === undefined) {
233	    throw new Error(`item not covered by the policy: ${damage.itemType}`);
234	  }
235	  return item;
236	};
237	
238	/**
239	 * What the MHPCO reimburses for ONE damaged item, before the deductible.
240	 * Highly enchanted items are reimbursed at half the damage amount.
241	 *
242	 * NOT A BUG: the spec's "dragon material is fully reimbursed" clause is
243	 * deliberately absent, because no example can observe it. Full reimbursement is
244	 * already what happens when no clause fires, so below enchantment 8 a dragon
245	 * item is indistinguishable from a steel one; at enchantment >= 8 the spec says
246	 * the 50 % rule wins, so dragon is indistinguishable again. The clause has no
247	 * input that would change an output — adding it would be unfalsifiable by the
248	 * suite. Both dragon tests below pass against this code for exactly the reasons
249	 * their comments state. If a future rule ever makes material observable (say, a
250	 * dragon-only exemption from the deductible, or a clause the 50 % rule does not
251	 * override), add it then, driven by that example.
252	 *
253	 * The enchantment is read from the FIRST policy item of the damaged type — see
254	 * `damagedItem`, which throws if the policy covers no such type at all. With
255	 * two alike items that differ in enchantment the wrong one would be consulted;
256	 * no example distinguishes them yet.
257	 */
258	const reimbursementFor = (damage: Damage, policyItems: Item[]): number =>
259	  enchantmentAtLeast(
260	    damagedItem(damage, policyItems),
261	    HIGH_ENCHANTMENT_PAYOUT_THRESHOLD,
262	  )
263	    ? percentOf(damage.amount, HIGH_ENCHANTMENT_PAYOUT_PERCENT)
264	    : damage.amount;
265	
266	/**
267	 * One damaged item's contribution to the payout. The deductible comes off ONCE
268	 * PER DAMAGED ITEM, not once per incident — expressing it at the level of a
269	 * single damage is what makes that per-item scope structural rather than a
270	 * remark about where a subtraction happens to sit.
271	 */
272	const payoutForDamage = (damage: Damage, policyItems: Item[]): number =>
273	  reimbursementFor(damage, policyItems) - DEDUCTIBLE;
274	
275	/**
276	 * The whole incident's payout, before rounding — the per-item payouts summed.
277	 * NOT named for reimbursement: `reimbursementFor` is the amount BEFORE the
278	 * deductible, and reusing that word here would invite a reader to subtract it
279	 * a second time.
280	 */
281	const payoutBeforeRounding = (incident: Incident, policyItems: Item[]): number =>
282	  incident.damages.reduce(
283	    (total, damage) => total + payoutForDamage(damage, policyItems),
284	    0,
285	  );
286	
287	/**
288	 * Anything that is not a claim is treated as a quote, which is why this names
289	 * the claim case rather than offering an `isQuote` counterpart: a two-sided
290	 * pair would imply a third possibility the code does not handle. See the Step
291	 * doc comment on why `op` is a plain string.
292	 */
293	const isClaim = (step: Step): boolean => step.op === "claim";
294	
295	/** A claim's `policy` field is the index of the quote step that wrote it. */
296	const itemsCoveredBy = (policy: number, scenario: Scenario): Item[] =>
297	  scenario.steps[policy].items ?? [];
298	
299	/** The MHPCO caps a policy at twice its insurance sum. */
300	const capFor = (policyItems: Item[]): number =>
301	  CAP_MULTIPLE * insuranceSum(policyItems);
302	
303	/**
304	 * A policy's cap is consumed cumulatively: each payout draws down what remains,
305	 * and a claim can never pay out more than is left. The clamp is applied AFTER
306	 * rounding, so a fractional payout cannot round its way past the remaining cap.
307	 *
308	 * Takes the policy's items and its remaining cap rather than looking either up,
309	 * which keeps the arithmetic of a single claim free of the ledger's bookkeeping.
310	 * `capLedger.settle` resolves both and is the only caller.
311	 */
312	const settleClaim = (
313	  incident: Incident,
314	  policyItems: Item[],
315	  remainingBefore: number,
316	): ClaimResult => {
317	  const desired = roundPayoutDown(payoutBeforeRounding(incident, policyItems));
318	  const payout = Math.min(desired, remainingBefore);
319	  return { payout, remainingCap: remainingBefore - payout };
320	};
321	
322	/**
323	 * Tracks what each policy has left of its cap as claims land against it, and
324	 * settles claims against it. A policy is seeded from its items the first time
325	 * it is claimed against, which is why this needs the scenario: the cap is a
326	 * property of the covered items, and those live in the quote step the claim
327	 * points at.
328	 *
329	 * Settling lives here rather than in the caller because the drawdown is the
330	 * whole reason the ledger exists: reading what remains, paying out of it, and
331	 * writing back what is left are one indivisible step, and a caller that could
332	 * read without writing back could silently let a policy pay twice over.
333	 */
334	const capLedger = (scenario: Scenario) => {
335	  const remainingByPolicy = new Map<number, number>();
336	
337	  return {
338	    settle: (policy: number, incident: Incident): ClaimResult => {
339	      const policyItems = itemsCoveredBy(policy, scenario);
340	      const remainingBefore =
341	        remainingByPolicy.get(policy) ?? capFor(policyItems);
342	      const result = settleClaim(incident, policyItems, remainingBefore);
343	      remainingByPolicy.set(policy, result.remainingCap);
344	      return result;
345	    },
346	  };
347	};
348	
349	/**
350	 * Steps are processed in order because claims draw down a policy's remaining
351	 * cap, so each result depends on the claims before it.
352	 */
353	export const runScenario = (scenario: Scenario): ScenarioResult => {
354	  const caps = capLedger(scenario);
355	
356	  const results = scenario.steps.map((step, precedingSteps) => {
357	    if (isClaim(step)) {
358	      // Non-null: only claim steps reach here, and every claim carries an
359	      // incident. See the Step doc comment.
360	      return caps.settle(step.policy ?? 0, step.incident!);
361	    }
362	
363	    return {
364	      premium: quotePremium(step.items ?? [], scenario.customer, precedingSteps),
365	    };
366	  });
367	
368	  return { results };
369	};
